interface Props {
  slug: string
  label?: string
  className?: string
  size?: number
  color?: string
}

export function BrandIcon({
  slug,
  label,
  className = '',
  size = 20,
  color,
}: Props) {
  const key = (ALIAS[slug.toLowerCase()] ?? slug.toLowerCase())
  const path = BRAND_PATHS[key]
  const title = label ?? slug

  if (path) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width={size}
        height={size}
        aria-label={title}
        className={className}
        style={color ? { color } : undefined}
      >
        <path d={path} fill="currentColor" />
      </svg>
    )
  }

  const initials = (label ?? slug)
    .split(/[\s\-_]/)
    .map((p) => p[0])
    .filter(Boolean)
    .slice(0, 2)
    .join('')
    .toUpperCase()
  return (
    <span
      role="img"
      aria-label={title}
      className={`inline-flex items-center justify-center rounded-md font-semibold ${className}`}
      style={{
        width: size,
        height: size,
        fontSize: Math.max(size * 0.42, 9),
        color: color ?? 'currentColor',
        background: 'rgba(255,255,255,0.06)',
      }}
    >
      {initials || '·'}
    </span>
  )
}
